/**
 * Monster illustrations from Figma node 354:79493.
 *
 * The source art draws each eye as a plain white ellipse with its pupil as a separate
 * shape on top, trimmed where it meets the rim. Refitting that trimmed shape recovers
 * the whole pupil, which is then clipped by the eye — identical at rest, but free to
 * drift up to travelX/travelY as the pointer moves.
 *
 * All geometry is already in the shared viewBox below; no per-monster transform.
 */

export interface MonsterEye {
  /** Eye centre, and where a pupil looking straight ahead sits. */
  cx: number;
  cy: number;
  /** Eye radii. */
  rx: number;
  ry: number;
  /** Eye tilt in degrees; the pupil's travel limits follow it. */
  rotate: number;
  pupilRx: number;
  pupilRy: number;
  /** Drift at full gaze, leaving the pupil just inside the eye rim. */
  travelX: number;
  travelY: number;
}

export interface Monster {
  id: string;
  color: string;
  bodyPaths: string[];
  eyes: MonsterEye[];
}

